arguments.file_text:
@page "/catalog"
@using sv_f3d43bcc69314410bf985495b673c661.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (errorMessage is not null)
{
    <div class="alert alert-error" role="alert">
        <p>@errorMessage</p>
        <button class="btn btn-secondary" @onclick="RetryLoad">Retry</button>
    </div>
}
else
{
    <div class="catalog-layout">
        <CatalogFilters Categories="categories"
                        OnApply="HandleApplyFilters"
                        OnClear="HandleClearFilters" />

        <main class="catalog-main">
            @if (isLoading)
            {
                <div class="loading-indicator" aria-live="polite">
                    <p>Loading products…</p>
                </div>
            }
            else if (result is not null)
            {
                <CatalogToolbar SortBy="@sortBy"
                                TotalCount="result.TotalCount"
                                Page="result.Page"
                                PageSize="result.PageSize"
                                OnSortChanged="HandleSortChanged" />

                <ProductGrid Products="result.Items"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                <CatalogPagination CurrentPage="currentPage"
                                   TotalPages="totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        </main>
    </div>
}

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> categories = [];
    private PagedResult<Product>? result;
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;
    private bool isLoading;
    private string? errorMessage;

    private int totalPages => result is null || result.PageSize == 0
        ? 0
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialData();
    }

    private async Task LoadInitialData()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            categories = await ProductService.GetCategoriesAsync();
            await SearchProducts();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to search products: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleClearFilters()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await SearchProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await SearchProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — hook into a cart service when available
        return Task.CompletedTask;
    }

    private async Task RetryLoad()
    {
        await LoadInitialData();
    }
}

h1 {
    margin-bottom: 1rem;
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

/* Sidebar filters: ~25% */
::deep .catalog-filters {
    flex: 0 0 25%;
    min-width: 220px;
    border-right: 1px solid #e0e0e0;
    padding-right: 1.5rem;
}

::deep .catalog-filters h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

::deep .catalog-filters h3 {
    font-size: 1rem;
    margin: 1rem 0 0.5rem;
}

::deep .filter-section {
    margin-bottom: 1rem;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

::deep .price-inputs {
    display: flex;
    gap: 0.75rem;
}

::deep .price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

::deep .price-inputs input {
    width: 90px;
    padding: 0.35rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
}

/* Main content: ~75% */
.catalog-main {
    flex: 1;
    min-width: 0;
}

/* Toolbar */
::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .sort-control select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .result-count {
    font-size: 0.9rem;
    color: #666;
}

/* Product grid */
::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
    display: flex;
    flex-direction: column;
}

::deep .product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

::deep .product-card.out-of-stock {
    opacity: 0.7;
}

::deep .product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
    text-align: center;
    padding: 0.5rem;
}

::deep .product-info {
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    flex: 1;
}

::deep .product-name {
    font-size: 1rem;
    margin: 0;
}

::deep .product-price {
    font-weight: 600;
    color: #2a7d2a;
    margin: 0;
}

::deep .product-rating {
    color: #f5a623;
    font-size: 1.1rem;
}

::deep .badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: #fff;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    align-self: flex-start;
}

/* Buttons */
::deep .btn {
    padding: 0.4rem 0.9rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    background: #fff;
}

::deep .btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

::deep .btn-primary {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

::deep .btn-secondary {
    background: #6c757d;
    color: #fff;
    border-color: #6c757d;
}

::deep .btn-add-to-cart {
    margin-top: auto;
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

/* Pagination */
::deep .catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

/* States */
.loading-indicator {
    text-align: center;
    padding: 3rem;
    color: #666;
}

::deep .empty-results {
    text-align: center;
    padding: 3rem;
    color: #666;
}

.alert-error {
    background: #f8d7da;
    color: #842029;
    padding: 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
}

